package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var LoanRecVar LoanRec

var loanLines []string
var loanIdx int
var loanOpen bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	if intDigits <= 0 {
		return decimal.NewFromInt(0)
	}
	neg := t.IsNegative()
	a := t
	if neg {
		a = a.Neg()
	}
	scaled := a.Shift(scale)
	divStr := "1" + strings.Repeat("0", intDigits+int(scale))
	div, _ := decimal.NewFromString(divStr)
	rem := scaled.Mod(div)
	res := rem.Shift(-scale)
	if neg {
		res = res.Neg()
	}
	return res
}

func formatEdited(v decimal.Decimal, pattern string) string {
	dot := strings.Index(pattern, ".")
	var intPat, fracPat string
	if dot >= 0 {
		intPat = pattern[:dot]
		fracPat = pattern[dot+1:]
	} else {
		intPat = pattern
		fracPat = ""
	}
	intSlots := 0
	for _, c := range intPat {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPat {
		if c == 'Z' || c == '9' || c == 'z' {
			fracSlots++
		}
	}
	neg := v.IsNegative()
	a := v
	if neg {
		a = a.Neg()
	}
	a = a.Truncate(int32(fracSlots))
	scaled := a.Shift(int32(fracSlots))
	// keep low-order digits
	if intSlots+fracSlots > 0 {
		divStr := "1" + strings.Repeat("0", intSlots+fracSlots)
		div, _ := decimal.NewFromString(divStr)
		scaled = scaled.Mod(div)
	}
	s := scaled.String()
	// scaled is integer >=0
	if strings.Contains(s, ".") {
		s = strings.Split(s, ".")[0]
	}
	if strings.HasPrefix(s, "-") {
		s = s[1:]
	}
	if len(s) < intSlots+fracSlots {
		s = strings.Repeat("0", intSlots+fracSlots-len(s)) + s
	} else if len(s) > intSlots+fracSlots {
		s = s[len(s)-(intSlots+fracSlots):]
	}
	intDigitsStr := ""
	fracDigitsStr := ""
	if fracSlots > 0 {
		intDigitsStr = s[:intSlots]
		fracDigitsStr = s[intSlots:]
	} else {
		intDigitsStr = s
	}
	// build integer part
	var outInt []rune
	digitIdx := 0
	significant := false
	// First pass to determine: we walk left to right
	for _, c := range intPat {
		switch c {
		case 'Z':
			d := intDigitsStr[digitIdx]
			digitIdx++
			if !significant && d == '0' {
				// check if any later significant? Actually suppression: leading zeros -> space
				// Need lookahead: if all remaining int digits are zero and no '9' forces? But '9' at end forces.
				// Simpler: space for now; if later we find significance, stays space (correct).
				outInt = append(outInt, ' ')
			} else {
				significant = true
				if d != '0' {
					// significant already
				}
				// if d=='0' but significant already, show 0
				outInt = append(outInt, rune(d))
				if d != '0' {
					significant = true
				}
			}
			if d != '0' {
				significant = true
			}
		case '9':
			d := intDigitsStr[digitIdx]
			digitIdx++
			significant = true
			outInt = append(outInt, rune(d))
		case ',':
			if significant {
				outInt = append(outInt, ',')
			} else {
				outInt = append(outInt, ' ')
			}
		case '.':
			outInt = append(outInt, '.')
		default:
			outInt = append(outInt, c)
		}
	}
	var outFrac []rune
	fIdx := 0
	for _, c := range fracPat {
		if c == '9' || c == 'Z' || c == 'z' {
			d := byte('0')
			if fIdx < len(fracDigitsStr) {
				d = fracDigitsStr[fIdx]
			}
			fIdx++
			outFrac = append(outFrac, rune(d))
		} else {
			outFrac = append(outFrac, c)
		}
	}
	var res string
	if dot >= 0 {
		res = string(outInt) + "." + string(outFrac)
	} else {
		res = string(outInt)
	}
	_ = neg
	return res
}

func parseImplied(field string, scale int32) decimal.Decimal {
	if len(field) == 0 {
		return decimal.NewFromInt(0)
	}
	// spaces -> zeros
	b := make([]byte, len(field))
	for i := 0; i < len(field); i++ {
		ch := field[i]
		if ch == ' ' {
			b[i] = '0'
		} else {
			b[i] = ch
		}
	}
	s := string(b)
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s should be digits (maybe sign?) - handle unsigned
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		// fallback via decimal
		d, err2 := decimal.NewFromString(s)
		if err2 != nil {
			return decimal.NewFromInt(0)
		}
		return d.Shift(-scale)
	}
	return decimal.New(n, -scale)
}

func parseIntField(field string) int64 {
	if len(field) == 0 {
		return 0
	}
	t := strings.TrimSpace(field)
	if t == "" {
		return 0
	}
	// spaces inside -> zeros?
	t = strings.ReplaceAll(field, " ", "0")
	t = strings.TrimSpace(t)
	n, err := strconv.ParseInt(strings.TrimSpace(t), 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func loadLoanFile() error {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			loanLines = nil
			return nil
		}
		return err
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	var lines []string
	for sc.Scan() {
		line := sc.Text()
		lines = append(lines, line)
	}
	if err := sc.Err(); err != nil {
		return err
	}
	loanLines = lines
	loanIdx = 0
	return nil
}

func READ_PARA() {
	if !loanOpen || loanIdx >= len(loanLines) {
		WsEofFlag = "Y"
		return
	}
	raw := loanLines[loanIdx]
	loanIdx++
	rec := padRight(raw, 21)
	LoanRecVar.LrAcct = rec[0:6]
	LoanRecVar.LrPrincipal = parseImplied(rec[6:15], 2)
	LoanRecVar.LrRate = parseImplied(rec[15:19], 2)
	LoanRecVar.LrYears = parseIntField(rec[19:21])
	// normalize principal/rate to scale 2 truncated? They are exact.
}

func PROCESS_PARA() {
	t := LoanRecVar.LrPrincipal.Mul(LoanRecVar.LrRate).Mul(decimal.NewFromInt(LoanRecVar.LrYears)).Shift(-2)
	t = t.Round(2)
	WsInterest = fitDecimal(t, 9, 2)
	WsTotal = fitDecimal(WsTotal.Add(WsInterest), 11, 2)
	WsCount = (WsCount + 1) % 100000
	WsPrinEd = formatEdited(LoanRecVar.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Fprintln(os.Stdout, LoanRecVar.LrAcct+" "+WsPrinEd+" "+WsIntEd)
	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount%100000)
	fmt.Fprintln(os.Stdout, "RECORDS: "+countStr)
	fmt.Fprintln(os.Stdout, "TOTAL INTEREST: "+WsTotalEd)
}

func MAIN_PARA() {
	loanOpen = true
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	loanOpen = false
	SUMMARY_PARA()
}

func main() {
	if err := loadLoanFile(); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	MAIN_PARA()
}
